@extends('layouts.app') @section('title','Appointments') @section('page-title','Appointments') @section('content')<div class="toolbar"><form class="filters" method="GET"><input name="q" value="{{ request('q') }}" placeholder="Client name…"><input type="date" name="date" value="{{ request('date') }}"><select name="status"><option value="">All statuses</option>@foreach(['pending','confirmed','completed','cancelled','no_show'] as $s)<option value="{{ $s }}" {{ request('status')===$s?'selected':'' }}>{{ ucfirst(str_replace('_',' ',$s)) }}</option>@endforeach</select><button class="btn btn-ghost">Filter</button></form><div><a class="btn btn-ghost" href="{{ route('appointments.calendar') }}">Calendar</a><a class="btn btn-primary" href="{{ route('appointments.create') }}">＋ New appointment</a></div></div><div class="table-card"><table><thead><tr><th>Date & time</th><th>Client</th><th>Service</th><th>Stylist</th><th>Status</th><th></th></tr></thead><tbody>@forelse($appointments as $a)<tr><td><b>{{ $a->appointment_date->format('d M Y') }}</b><small>{{ substr($a->start_time,0,5) }} – {{ substr($a->end_time,0,5) }}</small></td><td>{{ $a->client->full_name }}<small>{{ $a->client->phone }}</small></td><td>{{ $a->service->name }}<small>PKR {{ number_format($a->service->price) }}</small></td><td>{{ $a->staff->full_name }}</td><td><span class="status {{ $a->status }}">{{ str_replace('_',' ',$a->status) }}</span></td><td class="actions"><a href="{{ route('appointments.edit',$a) }}">Edit</a>@if(auth()->user()->role!=='stylist'&&$a->status!=='cancelled')<form method="POST" action="{{ route('appointments.destroy',$a) }}" onsubmit="return confirm('Cancel this appointment?')">@csrf @method('DELETE')<button>Cancel</button></form>@endif</td></tr>@empty<tr><td colspan="6" class="empty">No appointments found.</td></tr>@endforelse</tbody></table></div>{{ $appointments->links('partials.pagination') }}@endsection
